INSERT INTO app_records(collection,id,data_json,updated_at)
VALUES('public_site_settings','main','{"title":"Natara Konstruksi","tagline":"Membangun dengan Arah.","about":"Natara Konstruksi adalah perusahaan jasa konstruksi yang berfokus pada pembangunan yang terencana, terarah, dan bertanggung jawab. Kami hadir sebagai mitra pembangunan bagi klien yang menghargai proses, kejelasan kerja, dan kualitas jangka panjang. Bagi Natara, membangun bukan sekadar menyelesaikan bangunan, tetapi menata pembangunan dengan arah yang jelas dan tanggung jawab penuh—dari tahap perencanaan hingga serah terima.","philosophy":"Menata pembangunan dengan arah yang jelas dan tanggung jawab penuh.","vision":"Menjadi perusahaan konstruksi yang terpercaya dan berkelanjutan melalui sistem kerja yang terarah, profesional, dan bertanggung jawab.","mission":["Menyediakan layanan konstruksi yang terencana, terukur, dan sesuai standar teknis.","Menjaga amanah klien melalui transparansi biaya, waktu, dan proses kerja.","Mengedepankan pengawasan dan pengendalian mutu di setiap proyek.","Membangun hubungan jangka panjang dengan klien dan mitra kerja."],"values":[{"title":"Amanah","description":"Menjalankan setiap proyek dengan kejujuran dan tanggung jawab."},{"title":"Terstruktur","description":"Bekerja dengan sistem, perencanaan, dan alur kerja yang jelas."},{"title":"Profesional","description":"Didukung oleh tim dan proses yang rapi serta berorientasi pada kualitas."},{"title":"Berkelanjutan","description":"Fokus pada hasil jangka panjang, bukan sekadar penyelesaian cepat."}],"services":["Jasa Konstruksi","Renovasi & Pengembangan","Manajemen Proyek"],"serviceGroups":[{"title":"Jasa Konstruksi","items":["Pembangunan rumah tinggal","Bangunan komersial & usaha","Bangunan pendukung lainnya"]},{"title":"Renovasi & Pengembangan","items":["Renovasi bangunan eksisting","Pengembangan fungsi dan kualitas bangunan"]},{"title":"Manajemen Proyek","items":["Perencanaan dan pengendalian proyek","Pengawasan pelaksanaan di lapangan","Koordinasi dengan konsultan dan klien"]}],"approach":[{"title":"Perencanaan","description":"Analisis kebutuhan, penyusunan konsep, dan perhitungan teknis."},{"title":"Penataan & Persiapan","description":"Penyusunan anggaran, timeline, dan metode kerja."},{"title":"Pelaksanaan & Pengawasan","description":"Pekerjaan lapangan dengan kontrol mutu dan progres yang ketat."},{"title":"Evaluasi & Serah Terima","description":"Pemeriksaan hasil akhir dan penyelesaian proyek secara bertanggung jawab."}],"advantages":["Proses kerja jelas dan terstruktur","Fokus pada perencanaan dan pengawasan","Transparansi dalam komunikasi dan anggaran","Komitmen terhadap amanah dan kualitas"],"audience":["Ingin membangun dengan tenang","Menghargai proses dan kejelasan kerja","Berorientasi pada kualitas jangka panjang"],"closing":"Natara Konstruksi hadir untuk menjawab kebutuhan pembangunan yang tidak hanya kuat secara fisik, tetapi juga dapat dipertanggungjawabkan secara proses dan nilai.","portfolioIntro":"Portofolio karya Natara Konstruksi yang menampilkan visualisasi desain dan dokumentasi proyek."}',datetime('now'))
ON CONFLICT(collection,id) DO UPDATE SET
  data_json=json_patch(app_records.data_json,excluded.data_json),
  updated_at=datetime('now');

INSERT INTO app_records(collection,id,data_json,updated_at)
VALUES('public_portfolio','CP-LOSARI','{"published":true,"featured":true,"title":"Rumah Losari","slug":"rumah-losari","category":"Rumah Tinggal","year":"2026","location":"Makassar, Sulawesi Selatan","summary":"Hunian modern, fungsional, dan berestetika kontemporer untuk kebutuhan keluarga urban.","description":"Rumah Losari terletak di Kota Makassar, Sulawesi Selatan, berada pada kawasan berkembang yang kini menjadi salah satu koridor hunian paling dinamis di kota ini. Dengan luas tapak 180 m², proyek ini dirancang untuk menjawab kebutuhan keluarga urban yang menginginkan hunian modern, fungsional, dan berestetika kontemporer.","coverUrl":"/assets/company-profile/losari-cover.webp","galleryUrls":["/assets/company-profile/losari-interior-1.webp","/assets/company-profile/losari-interior-2.webp","/assets/company-profile/losari-interior-3.webp","/assets/company-profile/losari-interior-4.webp","/assets/company-profile/losari-progress-1.webp","/assets/company-profile/losari-progress-2.webp"],"specs":{"landArea":"180 m²","buildingArea":"235 m²","floors":"2","bedrooms":"5","bathrooms":"6","carport":"2"}}',datetime('now'))
